mkdir -p /tmp/scratch && cat > /tmp/scratch/T.java <<'EOF'
import org.apache.commons.lang3.ArrayUtils;
public class T {
    public static void main(String[] args) throws Exception {
        System.out.println("[" + ArrayUtils.toString(new Object[0]) + "]");
        System.out.println("[" + ArrayUtils.toString(null) + "]");
        System.out.println("[" + ArrayUtils.toString(new int[]{1,2}) + "]");
        System.out.println(ArrayUtils.isSameType(new int[0], "not an array"));
        String[] r = ArrayUtils.toStringArray(new Object[]{1, "a", null});
        System.out.println(r[0] + "|" + r[1] + "|" + r[2]);
    }
}
EOF
javac -cp target/classes -d /tmp/scratch /tmp/scratch/T.java && java -cp target/classes:/tmp/scratch T
